            ?catchment a envthes:30212 ;
                       geo:hasGeometry ?geom1 .
            ?geom1 a sf:Polygon ;
                   geo:asWKT ?wkt1 .
          }
          GROUP BY ?catchment ?wkt1
        }
        {
          SELECT (MAX(?sumPrecip) AS ?maxPrecip)
          WHERE {
            SELECT ?catchment (SUM(?precip) AS ?sumPrecip)
            WHERE {
              ?obs a sosa:Observation ;
                   sosa:observedProperty envthes:30106 ;
                   sosa:hasFeatureOfInterest ?catchment ;
                   sosa:resultTime ?time ;
                   sosa:hasResult ?value .
              ?value qudt:numericValue ?precip .
              FILTER (?time >= "2012-01-01"^^xsd:date && ?time <= "2015-12-31"^^xsd:date)
            }
            GROUP BY ?catchment
          }
        }
        FILTER (?totalPrecip = ?maxPrecip)
      }
      LIMIT 1
    }
    ?catchment2 a envthes:30212 ;
                geo:hasGeometry ?geom2 .
    ?geom2 a sf:Polygon ;
           geo:asWKT ?wkt2 .
    FILTER (?catchment2 != ?catchment)
    FILTER(geof:sfTouches(?wkt1, ?wkt2))
  }
}

